/* @lc app=leetcode id=3619 lang=kotlin */ class Solution { fun countIslands(grid: Array<IntArray>, k: Int): Int = grid.size.let { m -> grid[0].size.let { n -> BooleanArray(m * n).let { vis -> (0 until m * n).count { c -> grid[c / n][c % n] > 0 && !vis[c] && generateSequence(listOf(c).also { vis[c] = true }) { f -> f.flatMap { x -> listOf(x / n + 1 to x % n, x / n - 1 to x % n, x / n to x % n + 1, x / n to x % n - 1).filter { (a, b) -> a in 0 until m && b in 0 until n && grid[a][b] > 0 && !vis[a * n + b] }.map { (a, b) -> (a * n + b).also { vis[it] = true } } }.takeIf { it.isNotEmpty() } }.flatten().sumOf { grid[it / n][it % n].toLong() } % k == 0L } } } } }